<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>StylePress</title>{!! app(\Mothership\DAM\Http\Controllers\HomeToolController::class)->bootstrap("stylepress") !!}</head><body style="margin:0;font-family:Inter,system-ui,sans-serif">
<style>
.sp-shell{--bg:#0b0d12;--panel:#141927;--line:#2a3348;--text:#eef2ff;--muted:#9aa6c2;--brand:#8dd7ff;--hot:#d6a4ff;min-height:calc(100vh - 90px);background:radial-gradient(circle at 20% 0%,rgba(141,215,255,.18),transparent 32rem),radial-gradient(circle at 100% 10%,rgba(214,164,255,.16),transparent 30rem),var(--bg);color:var(--text);border-radius:18px;padding:22px;overflow:hidden}.sp-hero{display:flex;gap:18px;justify-content:space-between;margin-bottom:18px}.sp-title{font-size:34px;line-height:1;font-weight:900;letter-spacing:-.04em;margin:0}.sp-sub{color:var(--muted);max-width:760px;margin-top:8px}.sp-stats{display:flex;gap:10px;flex-wrap:wrap}.sp-stat{border:1px solid var(--line);background:rgba(255,255,255,.05);border-radius:14px;padding:10px 12px;min-width:110px}.sp-stat b{display:block;font-size:20px}.sp-grid{display:grid;grid-template-columns:280px minmax(0,1fr) 360px;gap:16px;min-height:650px}.sp-panel{background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.035));border:1px solid var(--line);border-radius:18px;box-shadow:0 24px 80px rgba(0,0,0,.25);min-width:0}.sp-sidebar,.sp-main,.sp-detail{padding:14px;display:flex;flex-direction:column;gap:12px}.sp-label{font-size:11px;text-transform:uppercase;letter-spacing:.16em;color:var(--muted);font-weight:800}.sp-search,.sp-select,.sp-textarea{width:100%;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.24);color:var(--text);padding:11px 12px;outline:none}.sp-textarea{min-height:116px;resize:vertical}.sp-chips{display:flex;flex-direction:column;gap:6px;max-height:440px;overflow:auto}.sp-chip{display:flex;justify-content:space-between;border:1px solid transparent;background:transparent;color:var(--muted);border-radius:11px;padding:9px 10px;cursor:pointer;text-align:left}.sp-chip:hover,.sp-chip.active{background:rgba(141,215,255,.11);border-color:rgba(141,215,255,.22);color:var(--text)}.sp-toolbar{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.sp-tabs{display:flex;gap:8px;flex-wrap:wrap}.sp-tab{border:1px solid var(--line);border-radius:999px;background:rgba(255,255,255,.04);color:var(--muted);padding:8px 11px;cursor:pointer}.sp-tab.active{color:#081018;background:linear-gradient(90deg,var(--brand),var(--hot));border-color:transparent;font-weight:800}.sp-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px;overflow:auto;padding-right:4px}.sp-card{position:relative;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#181d2a;cursor:pointer;text-align:left;color:inherit;padding:0}.sp-card.active{outline:2px solid var(--brand);box-shadow:0 0 0 6px rgba(141,215,255,.12)}.sp-thumb{aspect-ratio:4/5;width:100%;object-fit:cover;background:#0d1018;display:block}.sp-card-body{padding:10px}.sp-card-title{font-weight:800;font-size:13px;line-height:1.2}.sp-card-meta{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;margin-top:7px}.sp-preview{border-radius:15px;width:100%;aspect-ratio:4/5;object-fit:cover;background:#111827}.sp-detail h2{font-size:22px;line-height:1.05;margin:0}.sp-look{color:var(--muted);font-size:13px;line-height:1.45;max-height:128px;overflow:auto}.sp-slotlist{display:flex;gap:6px;flex-wrap:wrap}.sp-slot{font-size:11px;color:#d7e7ff;border:1px solid rgba(141,215,255,.25);background:rgba(141,215,255,.1);padding:4px 7px;border-radius:999px}.sp-actions{display:grid;gap:8px}.sp-btn{border:0;border-radius:12px;background:linear-gradient(90deg,var(--brand),var(--hot));color:#071018;font-weight:900;padding:11px 13px;cursor:pointer}.sp-btn.secondary{background:rgba(255,255,255,.06);color:var(--text);border:1px solid var(--line)}.sp-result{border:1px solid var(--line);border-radius:12px;padding:10px;background:rgba(0,0,0,.22);font-size:12px;white-space:pre-wrap;max-height:180px;overflow:auto;color:var(--muted)}.sp-empty{display:grid;place-items:center;color:var(--muted);min-height:300px;text-align:center}.sp-fav{position:absolute;right:8px;top:8px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.18);border-radius:999px;color:white;width:32px;height:32px;cursor:pointer}.sp-fav.on{background:#ffd166;color:#141414}@media(max-width:1180px){.sp-grid{grid-template-columns:240px minmax(0,1fr)}.sp-detail{grid-column:1/-1}}@media(max-width:760px){.sp-shell{padding:14px}.sp-hero{display:block}.sp-grid{grid-template-columns:1fr}.sp-title{font-size:28px}.sp-chips{max-height:180px}}
[hidden]{display:none!important}*{box-sizing:border-box}.sp-shell{min-height:100vh;border-radius:0}.sp-btn:disabled{opacity:.5;cursor:wait}
html[data-theme="light"] .sp-shell{--bg:#faf9fc;--panel:#fff;--line:#ddd8e4;--text:#251d31;--muted:#665b73;--brand:#bca6f3;--hot:#d6a4ff}
html[data-theme="light"] .sp-panel,html[data-theme="light"] .sp-card{background:#fff;box-shadow:0 8px 25px rgba(50,35,70,.05)}
html[data-theme="light"] .sp-search,html[data-theme="light"] .sp-select,html[data-theme="light"] .sp-textarea,html[data-theme="light"] .sp-result{background:#f5f2f8}
html[data-theme="light"] .sp-slot{color:#654989}
.sp-grid{grid-template-columns:200px minmax(280px,1fr) 320px;min-height:0;align-items:start}.sp-cards{max-height:65vh}.sp-preview{max-height:260px;object-fit:contain}.sp-detail{grid-column:auto}.sp-search:focus-visible,.sp-card:focus-visible,.sp-btn:focus-visible{outline:2px solid var(--brand);outline-offset:2px}.sp-grid{grid-template-columns:220px minmax(0,1fr) 340px}.sp-cards{max-height:72vh;scroll-padding-top:44px}.sp-density{display:flex;gap:4px;align-items:center}.sp-density .sp-tab{padding:6px 9px;font-size:12px}.sp-toolbar-right{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.sp-clear{border:0;background:transparent;color:var(--brand);cursor:pointer;font-size:12px;padding:0}.sp-cards{grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}.sp-cards[data-density=compact]{grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px}.sp-progress{display:flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:14px;padding:12px 14px;background:rgba(0,0,0,.22);color:var(--text)}.sp-progress p{margin:0;font-size:13px;line-height:1.35}.sp-progress small{display:block;color:var(--muted);margin-top:3px}.sp-spinner{flex:0 0 auto;width:28px;height:28px;border-radius:50%;border:3px solid rgba(141,215,255,.22);border-top-color:var(--brand);animation:sp-spin .9s linear infinite}@keyframes sp-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.sp-spinner{animation-duration:2.4s}}.sp-output{border:1px solid var(--line);border-radius:16px;overflow:hidden;background:#0d1018;display:flex;flex-direction:column}.sp-output-image{display:block;width:100%;max-height:70vh;object-fit:contain;background:#05070c;cursor:zoom-in}.sp-output-body{display:flex;flex-direction:column;gap:8px;padding:12px}.sp-output-title{font-weight:800;font-size:14px;line-height:1.25}.sp-output-meta{color:var(--muted);font-size:12px}.sp-output-actions{display:flex;flex-wrap:wrap;gap:8px}.sp-output-actions .sp-btn{padding:9px 11px;font-size:13px;text-decoration:none;display:inline-block}.sp-lightbox{border:0;padding:0;background:transparent;max-width:none;max-height:none;width:100%;height:100%}.sp-lightbox::backdrop{background:rgba(3,6,14,.9)}.sp-lightbox-panel{position:relative;width:100%;height:100%;display:grid;place-items:center;padding:24px;box-sizing:border-box}.sp-lightbox-panel img{max-width:100%;max-height:100%;object-fit:contain;box-shadow:0 30px 100px rgba(0,0,0,.6);border-radius:8px}.sp-lightbox-bar{position:absolute;top:14px;right:14px;display:flex;gap:8px}.sp-lightbox-bar .sp-btn{padding:8px 11px;font-size:13px;text-decoration:none}html[data-theme=light] .sp-output{background:#fff}html[data-theme=light] .sp-output-image{background:#f3f4f6}.sp-cards[data-density=compact] .sp-thumb{aspect-ratio:1/1}.sp-cards[data-density=compact] .sp-card-title{font-size:12px}.sp-cards[data-density=compact] .sp-card-meta{margin-top:4px}.sp-cards[data-density=compact] .sp-thumb.sp-empty{min-height:0;font-size:11px}.sp-cards[data-density=list]{display:flex;flex-direction:column;gap:6px}.sp-cards[data-density=list]>*{flex:0 0 auto}.sp-cards[data-density=list] .sp-card{display:grid;grid-template-columns:60px minmax(0,1fr);align-items:center;gap:10px;padding-right:46px;border-radius:12px;min-height:60px}.sp-cards[data-density=list] .sp-thumb{aspect-ratio:1/1;width:60px;height:60px;min-height:0;font-size:10px;line-height:1.2;text-align:center}.sp-cards[data-density=list] .sp-card-body{padding:6px 0}.sp-cards[data-density=list] .sp-card-meta{margin-top:3px}.sp-cards[data-density=list] .sp-fav{top:50%;transform:translateY(-50%)}.sp-group{grid-column:1/-1;position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 4px 6px;margin-top:4px;font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:var(--muted);background:linear-gradient(180deg,var(--panel) 80%,transparent)}.sp-group button{border:0;background:transparent;color:var(--brand);cursor:pointer;font:inherit;letter-spacing:0;text-transform:none;font-weight:700}.sp-sentinel{grid-column:1/-1;height:1px}.sp-card:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
.sp-asset-dialog{border:0;padding:0;background:transparent;max-width:none;max-height:none;width:100%;height:100%}.sp-asset-dialog::backdrop{background:rgba(3,6,14,.72);backdrop-filter:blur(3px)}.sp-asset-panel{box-sizing:border-box;margin:3vh auto;width:min(1200px,96vw);height:min(90vh,920px);display:flex;flex-direction:column;gap:10px;padding:16px 18px;border-radius:18px;border:1px solid var(--line);background:var(--panel);color:var(--text);box-shadow:0 40px 120px rgba(0,0,0,.5)}.sp-asset-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.sp-asset-head h2{margin:0;font-size:20px;letter-spacing:-.02em}.sp-lib{flex:1 1 auto;min-height:0;display:grid;grid-template-columns:250px minmax(0,1fr);gap:12px}.sp-lib-tree{min-height:0;overflow:auto;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18);padding:8px;font-size:13px}.sp-lib-entry{display:flex;align-items:center;gap:6px;width:100%;border:0;background:transparent;color:var(--text);text-align:left;padding:7px 8px;border-radius:9px;cursor:pointer;font:inherit;font-size:13px}.sp-lib-entry:hover{background:rgba(141,215,255,.1)}.sp-lib-entry.active{background:rgba(141,215,255,.18);font-weight:800}.sp-lib-entry .sp-lib-toggle{flex:0 0 18px;width:18px;height:18px;display:grid;place-items:center;border-radius:5px;color:var(--muted);font-size:11px}.sp-lib-entry .sp-lib-toggle.leaf{visibility:hidden}.sp-lib-entry .sp-lib-name{flex:1 1 auto;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.sp-lib-children{margin-left:16px;border-left:1px solid var(--line);padding-left:4px}.sp-lib-children[hidden]{display:none}.sp-lib-more{margin-left:34px;font-size:12px;color:var(--brand);background:transparent;border:0;cursor:pointer;padding:4px 0}.sp-lib-section{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:800;padding:8px 8px 4px}.sp-lib-main{min-height:0;display:flex;flex-direction:column;gap:8px}.sp-asset-tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.sp-asset-tools .sp-search{flex:1 1 240px}.sp-asset-tools .sp-select{width:auto}.sp-asset-crumbs{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12px;color:var(--muted);min-height:18px}.sp-asset-crumbs b{color:var(--text)}.sp-asset-grid{flex:1 1 auto;min-height:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:12px;overflow:auto;align-content:start;padding:2px}.sp-asset{display:block;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#0d1018;padding:0;cursor:pointer;color:var(--text);text-align:left;position:relative;user-select:none}.sp-asset:focus-visible{outline:2px solid var(--brand);outline-offset:2px}.sp-asset-thumb{position:relative;width:100%;height:0;padding-bottom:100%;background:#111827;overflow:hidden}.sp-asset-thumb img{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;display:block}.sp-asset-name{display:block;font-size:12px;line-height:1.3;padding:7px 8px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.sp-asset-mark{position:absolute;top:8px;right:8px;width:26px;height:26px;border-radius:999px;border:2px solid rgba(255,255,255,.7);background:rgba(0,0,0,.45);display:grid;place-items:center;font-size:14px;font-weight:900;color:transparent}.sp-asset.selected{outline:2px solid var(--brand);box-shadow:0 0 0 5px rgba(141,215,255,.16)}.sp-asset.selected .sp-asset-mark{background:var(--brand);border-color:var(--brand);color:#071018}.sp-asset.added{cursor:default;opacity:.55}.sp-asset.added .sp-asset-mark{background:#7bd88f;border-color:#7bd88f;color:#071018}.sp-asset-status{font-size:12px;color:var(--muted);margin:0}.sp-asset-foot{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.sp-asset-foot .sp-btn{width:auto}.sp-asset-more{grid-column:1/-1}.sp-asset-close{width:36px;height:36px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.06);color:var(--text);cursor:pointer;font-size:16px}@media(max-width:900px){.sp-lib{grid-template-columns:1fr}.sp-lib-tree{max-height:160px}}
html[data-theme="light"] .sp-asset{background:#fff}html[data-theme="light"] .sp-asset-thumb{background:#eee}html[data-theme="light"] .sp-lib-tree{background:#f6f7fb}
@media(max-width:1180px){.sp-grid{grid-template-columns:180px minmax(220px,1fr) 280px}.sp-detail{grid-column:auto}}
@media(max-width:900px){.sp-grid{grid-template-columns:minmax(0,1fr) 260px}.sp-sidebar{grid-column:1/-1}.sp-chips{flex-direction:row;flex-wrap:wrap;max-height:110px}.sp-cards{max-height:55vh}}
@media(max-width:760px){.sp-grid{grid-template-columns:1fr}.sp-sidebar,.sp-detail{grid-column:auto}.sp-cards{max-height:48vh}}
</style>

<div class="sp-shell" data-connected="{{ $generationAvailable ? '1' : '0' }}" data-generate-url="{{ $generateUrl }}" data-estimate-url="{{ $estimateUrl }}" data-balance-url="{{ $balanceUrl }}" data-csrf="{{ csrf_token() }}">
    <div class="sp-hero">
        <div>
            <h1 class="sp-title">StylePress for {{ config('documentation.name') }}</h1>
            <div class="sp-sub">House styles for your next idea.</div>
        </div>
        <div class="sp-stats">
            <div class="sp-stat"><b>{{ $catalog['count'] ?? 0 }}</b><span>styles</span></div>
            <div class="sp-stat"><b>{{ count($catalog['categories'] ?? []) }}</b><span>categories</span></div>
            <div class="sp-stat"><b>Higgsfield</b><span>shared work account</span></div>
        </div>
    </div>
    <div class="sp-grid">
        <aside class="sp-panel sp-sidebar">
            <div class="sp-label">Find styles</div>
            <input id="sp-search" class="sp-search" placeholder="Search style, use case, slot, hazard...">
            <select id="sp-aspect" class="sp-select"><option value="all">All aspect ratios</option><option>1:1</option><option>2:3</option><option>3:2</option><option>3:4</option><option>4:3</option><option>4:5</option><option>16:9</option><option>9:16</option><option>21:9</option></select>
            <select id="sp-sort" class="sp-select"><option value="relevance">Relevance</option><option value="title">A-Z</option><option value="recent">Recently used</option><option value="favorites">Favorites first</option></select>
            <div class="sp-label">Categories</div><div id="sp-categories" class="sp-chips"></div>
        </aside>
        <main class="sp-panel sp-main">
            <div class="sp-toolbar"><div class="sp-tabs"><button class="sp-tab active" data-tab="all">All</button><button class="sp-tab" data-tab="favorites">Favorites</button><button class="sp-tab" data-tab="recent">Recent</button><button class="sp-tab" data-tab="needs-slots">Needs slots</button></div><div class="sp-toolbar-right"><span id="sp-visible" class="sp-label"></span><button id="sp-clear" class="sp-clear" type="button" hidden>Clear filters</button><div class="sp-density" role="group" aria-label="Card size"><button class="sp-tab" data-density="comfortable" type="button" title="Large cards">Large</button><button class="sp-tab" data-density="compact" type="button" title="Compact cards">Compact</button><button class="sp-tab" data-density="list" type="button" title="List">List</button></div><label class="sp-label" style="display:flex;gap:6px;align-items:center;cursor:pointer"><input id="sp-group" type="checkbox"> Group by category</label></div></div>
            <div id="sp-cards" class="sp-cards"></div><div id="sp-empty" class="sp-empty" hidden>No matching styles. Broaden search or switch category.</div>
        </main>
        <section class="sp-panel sp-detail">
            <div id="sp-output" class="sp-output" hidden></div>
            <dialog id="sp-lightbox" class="sp-lightbox" aria-label="Generated image"><div class="sp-lightbox-panel"><img id="sp-lightbox-image" alt="Generated image"><div class="sp-lightbox-bar"><a id="sp-lightbox-open" class="sp-btn secondary" target="_blank" rel="noopener noreferrer">Open in new tab</a><button id="sp-lightbox-close" class="sp-btn secondary" type="button">Close</button></div></div></dialog>
            <img id="sp-preview" class="sp-preview" alt="Selected style preview">
            <div><div id="sp-cat" class="sp-label"></div><h2 id="sp-title"></h2></div>
            <div id="sp-look" class="sp-look"></div>
            <details id="sp-sources" hidden><summary>Source note and style pack</summary><div id="sp-source-files" style="display:flex;flex-direction:column;gap:6px;max-height:240px;overflow:auto;margin-top:8px;overflow-wrap:anywhere"></div></details>
            <div><div class="sp-label">Slot contract</div><div id="sp-slots" class="sp-slotlist"></div></div>
            <div class="sp-actions">
                <textarea id="sp-prompt" class="sp-textarea" placeholder="Describe the asset, campaign, brand, product, or utility you want to create..."></textarea>
                <p id="sp-prompt-count" class="sp-label" style="text-transform:none;letter-spacing:0">0 / 5000 characters · Enhance accepts up to 4000</p>
                <select id="sp-mode" class="sp-select"><option value="create">Create new image</option><option value="restyle">Restyle source image</option></select>
                <label class="sp-label" for="sp-output-aspect">Output aspect ratio</label>
                <select id="sp-output-aspect" class="sp-select"><option value="">Use style default</option><option>auto</option><option>1:1</option><option>4:3</option><option>3:4</option><option>16:9</option><option>21:9</option><option>9:16</option><option>3:2</option><option>2:3</option></select>
                <label class="sp-label" for="sp-model">Model</label>
                <select id="sp-model" class="sp-select"><option value="gpt_image_2_5:flare" selected>GPT Image 2.5 · Flare — fast, polished default</option><option value="gpt_image_2_5:sunburst">GPT Image 2.5 · Sunburst — alternate rendering profile</option><option value="gpt_image_2">GPT Image 2 · Standard</option></select>
                <label class="sp-label" for="sp-quality">Quality</label><select id="sp-quality" class="sp-select"><option value="low">Low</option><option value="medium">Medium</option><option value="high" selected>High</option></select>
                <label class="sp-label" for="sp-resolution">Resolution</label><select id="sp-resolution" class="sp-select"><option>1k</option><option selected>2k</option><option>4k</option></select>
                <label class="sp-label" for="sp-upload">Reference images <span id="sp-ref-count">0/8</span></label><input id="sp-upload" type="file" accept="image/png,image/jpeg,image/webp" multiple>
                <div id="sp-references" style="display:flex;gap:8px;flex-wrap:wrap"></div>
                <button id="sp-browse-assets" class="sp-btn secondary" type="button">Browse {{ config('documentation.name') }} images…</button>
                <dialog id="sp-asset-dialog" class="sp-asset-dialog" aria-labelledby="sp-asset-heading">
                    <div class="sp-asset-panel">
                        <div class="sp-asset-head"><h2 id="sp-asset-heading">Add from {{ config('documentation.name') }}</h2><button id="sp-asset-close" class="sp-asset-close" type="button" aria-label="Close">✕</button></div>
                        <div class="sp-lib">
                            <nav id="sp-lib-tree" class="sp-lib-tree" aria-label="Library folders">
                                <div class="sp-lib-section">Library</div>
                                <button class="sp-lib-entry active" data-kind="all" type="button"><span class="sp-lib-toggle leaf"></span><span class="sp-lib-name">All images</span></button>
                                <button class="sp-lib-entry" data-kind="recent" type="button"><span class="sp-lib-toggle leaf"></span><span class="sp-lib-name">Added in the last 30 days</span></button>
                                <button class="sp-lib-entry" data-kind="favorites" type="button"><span class="sp-lib-toggle leaf"></span><span class="sp-lib-name">Favorites</span></button>
                                <div class="sp-lib-section">Folders</div>
                                <div id="sp-lib-folders"><p class="sp-asset-status" style="padding:4px 8px">Loading folders…</p></div>
                            </nav>
                            <div class="sp-lib-main">
                                <div class="sp-asset-tools"><input id="sp-asset-search" class="sp-search" type="search" placeholder="Search all images by name, title, or tag" autocomplete="off"><select id="sp-asset-sort" class="sp-select" aria-label="Sort"><option value="newest">Newest first</option><option value="name">Name A–Z</option></select></div>
                                <div id="sp-asset-crumbs" class="sp-asset-crumbs"></div>
                                <p id="sp-asset-status" class="sp-asset-status" aria-live="polite"></p>
                                <div id="sp-asset-results" class="sp-asset-grid" role="listbox" aria-multiselectable="true"></div>
                            </div>
                        </div>
                        <div class="sp-asset-foot"><span id="sp-asset-selection" class="sp-asset-status">Click images to select them.</span><div style="display:flex;gap:8px"><button id="sp-asset-cancel" class="sp-btn secondary" type="button">Cancel</button><button id="sp-asset-add" class="sp-btn" type="button" disabled>Add selected</button></div></div>
                    </div>
                </dialog>
                <button id="sp-enhance" class="sp-btn secondary">Enhance request</button>
