</div>
<script type="application/json" id="sp-catalog">{!! json_encode($catalog, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE) !!}</script>
<script>
(()=>{const catalog=JSON.parse(document.getElementById('sp-catalog').textContent||'{}'),styles=catalog.presets||[],shell=document.querySelector('.sp-shell'),$=id=>document.getElementById(id),load=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(f))}catch{return f}},save=(k,v)=>localStorage.setItem(k,JSON.stringify(v)),state={q:'',cat:'All',aspect:'all',tab:'all',sort:'relevance',selected:styles[0]||null,favorites:load('sp:favorites',[]),recent:load('sp:recent',[]),density:load('sp:density','comfortable'),group:load('sp:group',true),limit:72};const CHUNK=72;const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),url=p=>'{{ url('admin/home/stylepress/thumbnail') }}/'+encodeURIComponent(p)+'?v='+encodeURIComponent(catalog.version||'unknown'),score=s=>{const h=[s.title,s.categoryLabel,s.look,(s.slotNames||[]).join(' ')].join(' ').toLowerCase();return state.q?(h.includes(state.q)?2:0)+(String(s.title).toLowerCase().includes(state.q)?3:0):1};function filtered(){let a=styles.filter(s=>(state.cat==='All'||s.categoryLabel===state.cat)&&(state.aspect==='all'||s.aspectRatio===state.aspect||s.nativeFormat===state.aspect)&&(!state.q||score(s)>0));if(state.tab==='favorites')a=a.filter(s=>state.favorites.includes(s.slug));if(state.tab==='recent')a=a.filter(s=>state.recent.includes(s.slug));if(state.tab==='needs-slots')a=a.filter(s=>(s.slotNames||[]).length>0);return a.sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):state.sort==='recent'?state.recent.indexOf(a.slug)-state.recent.indexOf(b.slug):state.sort==='favorites'?(state.favorites.includes(b.slug)-state.favorites.includes(a.slug))||score(b)-score(a):score(b)-score(a))}function cats(){const counts=new Map();styles.forEach(s=>counts.set(s.categoryLabel,(counts.get(s.categoryLabel)||0)+1));$('sp-categories').innerHTML=['All',...(catalog.categories||[])].map(c=>`<button class="sp-chip ${state.cat===c?'active':''}" data-cat="${esc(c)}"><span>${esc(c)}</span><span>${c==='All'?styles.length:counts.get(c)||0}</span></button>`).join('')}function cardHtml(s){return `<div class="sp-card ${state.selected?.slug===s.slug?'active':''}" data-slug="${esc(s.slug)}" role="button" tabindex="0" aria-pressed="${state.selected?.slug===s.slug}"><button class="sp-fav ${state.favorites.includes(s.slug)?'on':''}" data-fav="${esc(s.slug)}" type="button" aria-label="Favorite">★</button>${s.image?`<img class="sp-thumb" src="${url(s.slug)}" loading="lazy" decoding="async" alt="">`:`<div class="sp-thumb sp-empty">Reference entry</div>`}<div class="sp-card-body"><div class="sp-card-title">${esc(s.title)}</div><div class="sp-card-meta"><span>${esc(s.categoryLabel)}</span><span>${esc(s.aspectRatio)}</span></div></div></div>`}
function entries(){const a=filtered();const grouped=state.group&&state.cat==='All'&&!state.q&&state.sort==='relevance'&&state.tab==='all';if(!grouped)return{list:a.map(s=>({style:s})),count:a.length};const order=new Map((catalog.categories||[]).map((c,i)=>[c,i]));const by=new Map();a.forEach(s=>{if(!by.has(s.categoryLabel))by.set(s.categoryLabel,[]);by.get(s.categoryLabel).push(s)});const list=[];[...by.keys()].sort((x,y)=>(order.get(x)??999)-(order.get(y)??999)||x.localeCompare(y)).forEach(c=>{list.push({group:c,count:by.get(c).length});by.get(c).forEach(s=>list.push({style:s}))});return{list,count:a.length}}
let rendered=0,cardObserver=null;
function cards(append=false){const box=$('sp-cards'),{list,count}=entries();if(!append){state.limit=CHUNK;rendered=0;box.replaceChildren();box.scrollTop=0}$('sp-visible').textContent=`${count} visible`;$('sp-empty').hidden=count!==0;$('sp-clear').hidden=!(state.q||state.cat!=='All'||state.aspect!=='all'||state.tab!=='all');box.dataset.density=state.density;box.querySelector('.sp-sentinel')?.remove();const slice=list.slice(rendered,state.limit);const html=slice.map(e=>e.group!==undefined?`<div class="sp-group" data-group="${esc(e.group)}"><span>${esc(e.group)} · ${e.count}</span><button type="button" data-cat="${esc(e.group)}">Show only</button></div>`:cardHtml(e.style)).join('');box.insertAdjacentHTML('beforeend',html);rendered=Math.min(list.length,state.limit);if(rendered<list.length){const sentinel=document.createElement('div');sentinel.className='sp-sentinel';box.append(sentinel);if(!cardObserver)cardObserver=new IntersectionObserver(hits=>{if(hits.some(h=>h.isIntersecting)){state.limit+=CHUNK;cards(true)}},{root:box,rootMargin:'400px 0px'});cardObserver.observe(sentinel)}}
function markSelected(){document.querySelectorAll('#sp-cards .sp-card').forEach(c=>{const on=c.dataset.slug===state.selected?.slug;c.classList.toggle('active',on);c.setAttribute('aria-pressed',String(on))})}
function detail(){const s=state.selected;if(!s)return;availability();const sourceFiles=s.references||[];$('sp-sources').hidden=!sourceFiles.length;$('sp-source-files').innerHTML=sourceFiles.map((path,index)=>`<a style="color:var(--brand)" href="{{ url('admin/home/stylepress/source') }}/${encodeURIComponent(s.slug)}/${index}" target="_blank" rel="noopener">${esc(path.split('/').slice(2).join('/')||path)}</a>`).join('');$('sp-preview').hidden=!s.image;if(s.image)$('sp-preview').src=url(s.slug);$('sp-cat').textContent=`${s.categoryLabel} · ${s.aspectRatio}`;$('sp-title').textContent=s.title;$('sp-look').textContent=(s.generatable===false?'Reference-only entry. Browse and copy its source; generation is unavailable. ':'')+(s.look||'');$('sp-slots').innerHTML=(s.slotNames||[]).length?s.slotNames.map(x=>`<span class="sp-slot">{${esc(x)}}</span>`).join(''):'<span class="sp-slot">No required slots detected</span>'}function select(slug){reuseAssetId=null;invalidateEnhancement();const s=styles.find(x=>x.slug===slug);if(!s)return;state.selected=s;state.recent=[slug,...state.recent.filter(x=>x!==slug)].slice(0,30);save('sp:recent',state.recent);if(state.tab==='recent'||state.sort==='recent')cards();else markSelected();detail()}function compiled(){const s=state.selected,req=(acceptedEnhancement?$('sp-enhanced').value:$('sp-prompt').value).trim()||'Create a finished image using this style.';return ['STYLEPRESS HOUSE STYLE — LOCKED PRODUCTION INSTRUCTION',`STYLE: ${s.title}`,`STYLE LOOK: ${s.look}`,'STYLE TEMPLATE (VERBATIM):',s.template,s.slots?'INPUT SLOT CONTRACT (VERBATIM):':'',s.slots||'',$('sp-mode').value==='restyle'?'RESTYLE MODE: preserve source content and change only the style treatment.':'CREATE MODE: user request supplies content; style supplies art direction.','USER REQUEST:',req,'Produce exactly one finished image. No watermark, no prompt text, no implementation notes.'].filter(Boolean).join('\n\n')}function rerender(){cats();cards();detail()}$('sp-search').oninput=e=>{state.q=e.target.value.trim().toLowerCase();cards()};$('sp-aspect').onchange=e=>{state.aspect=e.target.value;cards()};$('sp-sort').onchange=e=>{state.sort=e.target.value;cards()};document.querySelector('.sp-tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;state.tab=b.dataset.tab;e.currentTarget.querySelectorAll('.sp-tab').forEach(x=>x.classList.toggle('active',x===b));cards()};$('sp-categories').onclick=e=>{const b=e.target.closest('[data-cat]');if(!b)return;state.cat=b.dataset.cat;rerender()};$('sp-clear').onclick=()=>{state.q='';state.cat='All';state.aspect='all';state.tab='all';$('sp-search').value='';$('sp-aspect').value='all';document.querySelectorAll('.sp-main .sp-tabs [data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab==='all'));rerender()};function paintDensity(){document.querySelectorAll('[data-density]').forEach(b=>{if(b.tagName==='BUTTON')b.classList.toggle('active',b.dataset.density===state.density)});$('sp-group').checked=!!state.group}document.querySelector('.sp-density').onclick=e=>{const b=e.target.closest('button[data-density]');if(!b)return;state.density=b.dataset.density;save('sp:density',state.density);paintDensity();cards()};$('sp-group').onchange=e=>{state.group=e.target.checked;save('sp:group',state.group);cards()};paintDensity();$('sp-cards').onclick=e=>{const only=e.target.closest('.sp-group [data-cat]');if(only){state.cat=only.dataset.cat;rerender();return}const fav=e.target.closest('[data-fav]');if(fav){e.stopPropagation();const slug=fav.dataset.fav;state.favorites=state.favorites.includes(slug)?state.favorites.filter(x=>x!==slug):[slug,...state.favorites];save('sp:favorites',state.favorites);fav.classList.toggle('on',state.favorites.includes(slug));if(state.tab==='favorites'||state.sort==='favorites')cards();return}const c=e.target.closest('[data-slug]');if(c)select(c.dataset.slug)};async function post(url,payload){const form=payload instanceof FormData;const r=await fetch(url,{method:'POST',headers:{...(!form?{'Content-Type':'application/json'}:{}),'X-CSRF-TOKEN':shell.dataset.csrf,'Accept':'application/json'},body:form?payload:JSON.stringify(payload)});return r.json()}function modelChoice(){const [model,variant]=$('sp-model').value.split(':');return{model,variant:variant||null}}function payload(){const s=state.selected;return{style_slug:s.slug,reuse_asset:reuseAssetId,prompt:$('sp-prompt').value,aspect_ratio:$('sp-output-aspect').value||s.aspectRatio,quality:$('sp-quality').value,resolution:$('sp-resolution').value,...modelChoice(),mode:$('sp-mode').value,references:references.map(r=>r.id),enhanced_prompt:acceptedEnhancement?$('sp-enhanced').value:null}}async function balance(){try{const r=await fetch(shell.dataset.balanceUrl,{headers:{'Accept':'application/json'}});const d=await r.json();$('sp-balance').textContent=d.ok?`Shared Higgsfield balance: ${d.balance?.credits ?? "Unavailable"} credits`:`Balance unavailable: ${d.message}`}catch(e){$('sp-balance').textContent=`Balance unavailable: ${String(e)}`}}$('sp-copy').onclick=async()=>{await navigator.clipboard.writeText(compiled());$('sp-result').hidden=false;$('sp-result').textContent='Compiled prompt copied.'};$('sp-estimate').onclick=async()=>{$('sp-result').hidden=false;$('sp-result').textContent='Estimating credits…';try{const d=await post(shell.dataset.estimateUrl,payload());const e=d.estimate||{};$('sp-result').textContent=d.ok?`Estimate: ${e.credits??JSON.stringify(e)} credits${e.usd?` / ${e.usd} USD`:''}${e.aspect_ratio?` · ${e.aspect_ratio} output`:''}`:JSON.stringify(d,null,2)}catch(err){$('sp-result').textContent=String(err)}finally{availability()}};let polling=false,pendingGeneration=load('sp:job',null);
function showProgress(text,detail){const box=$('sp-result');box.hidden=false;box.replaceChildren();const wrap=document.createElement('div');wrap.className='sp-progress';const spin=document.createElement('div');spin.className='sp-spinner';spin.setAttribute('role','status');spin.setAttribute('aria-label','Working');const p=document.createElement('p');p.textContent=text;if(detail){const small=document.createElement('small');small.textContent=detail;p.append(small)}wrap.append(spin,p);box.append(wrap)}
function showOutput(generation){
 const box=$('sp-result'),panel=$('sp-output');box.hidden=false;box.replaceChildren();
 if(generation.status!=='completed'){box.textContent=`Generation ended as ${generation.status}.`;return;}
 let url;try{url=new URL(generation.url,location.href);if(!['http:','https:'].includes(url.protocol)||url.origin!==location.origin)throw Error();}catch{box.textContent='Generation completed without a downloadable image URL.';return;}
 box.hidden=true;panel.replaceChildren();panel.hidden=false;
 const image=document.createElement('img');image.className='sp-output-image';image.src=url.href;image.alt='Generated image';image.title='View full size';image.onclick=()=>openLightbox(url.href);
 const body=document.createElement('div');body.className='sp-output-body';
 const title=document.createElement('div');title.className='sp-output-title';title.textContent='Your image is ready';
 const meta=document.createElement('div');meta.className='sp-output-meta';meta.textContent=generation.archive_status==='archived'?'Saved to {{ config('documentation.name') }} · Archived to the vault':'Saved to {{ config('documentation.name') }} · Vault archive pending device sync';
 const actions=document.createElement('div');actions.className='sp-output-actions';
 const view=document.createElement('button');view.type='button';view.className='sp-btn';view.textContent='View full size';view.onclick=()=>openLightbox(url.href);actions.append(view);
 const open=document.createElement('a');open.className='sp-btn secondary';open.href=url.href;open.target='_blank';open.rel='noopener noreferrer';open.textContent='Open image in new tab';actions.append(open);
 if(generation.asset_id){const download=document.createElement('a');download.className='sp-btn secondary';download.href='{{ url('admin/dam/assets') }}/'+generation.asset_id+'/generation/output?download=1';download.download='';download.textContent='Download';actions.append(download);const details=document.createElement('a');details.className='sp-btn secondary';details.href='{{ url('admin/dam/assets') }}/'+generation.asset_id+'/generation/view';details.target='_blank';details.rel='noopener';details.textContent='Generation details';actions.append(details)}
 body.append(title,meta,actions);panel.append(image,body);panel.scrollIntoView({behavior:'smooth',block:'nearest'});
}
const lightbox=$('sp-lightbox');function openLightbox(href){$('sp-lightbox-image').src=href;$('sp-lightbox-open').href=href;if(typeof lightbox.showModal==='function'){if(!lightbox.open)lightbox.showModal()}else lightbox.setAttribute('open','')}
function closeLightbox(){if(lightbox.open&&typeof lightbox.close==='function')lightbox.close();else lightbox.removeAttribute('open')}
$('sp-lightbox-close').onclick=closeLightbox;lightbox.onclick=e=>{if(e.target===lightbox||e.target.classList.contains('sp-lightbox-panel'))closeLightbox()};
async function pollGeneration(job){
 polling=true;availability();showProgress('Checking your generation…');
 const deadline=Date.now()+600000;
 try{
  const url=new URL(job.status_url,location.href);if(url.origin!==location.origin)throw Error('Invalid generation status address.');
  while(Date.now()<deadline){
   const response=await fetch(url.href,{headers:{Accept:'application/json'}});const data=await response.json();
   if(!response.ok)throw Error(data.message||'Status is temporarily unavailable.');
   if(['completed','failed','nsfw','canceled','cancelled'].includes(data.generation.status)){
    pendingGeneration=null;localStorage.removeItem('sp:job');showOutput(data.generation);return;
   }
   showProgress(data.generation.status==='saving'?'Image completed. Saving to {{ config('documentation.name') }}…':'Generating your image…',(data.generation.status==='saving'?'':'You can close this browser; the server keeps working. ')+(data.generation.message||''));
   await new Promise(resolve=>setTimeout(resolve,2500));
  }
  throw Error('Your generation is still processing.');
 }catch(error){
  $('sp-result').textContent=error.message+' ';
  const retry=document.createElement('button');retry.className='sp-btn secondary';retry.textContent='Check again';retry.onclick=()=>pollGeneration(job);$('sp-result').append(retry);
 }finally{polling=false;availability();}
}
$('sp-generate').onclick=async()=>{
 if(polling||pendingGeneration)return;
 if(!$('sp-enhancement').hidden&&$('sp-enhanced').value.trim()&&!acceptedEnhancement){if(confirm('Generate with the enhanced request shown below? Cancel to generate with your original request instead.')){acceptedEnhancement=true;enhancementStale=false;$('sp-reenhance').hidden=true;$('sp-enhancement-state').textContent='Accepted for this generation.'}else{$('sp-enhancement-state').textContent='Generating with the original request. The enhanced text is kept here for later.'}}
 polling=true;availability();$('sp-output').hidden=true;showProgress('Estimating, then submitting to Higgsfield…');
 try{
  const data=await post(shell.dataset.generateUrl,payload());if(!data.ok)throw Error(data.message||'Generation could not start.');
  pendingGeneration=data.generation;localStorage.setItem('sp:job',JSON.stringify(pendingGeneration));await pollGeneration(pendingGeneration);
 }catch(error){$('sp-result').textContent=error.message;}
 finally{polling=false;availability();}
};
$('sp-cards').onkeydown=e=>{const card=e.target.closest('[data-slug]');if(!card||e.target!==card)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();select(card.dataset.slug);return}const keys=['ArrowRight','ArrowLeft','ArrowDown','ArrowUp'];if(!keys.includes(e.key))return;e.preventDefault();const all=[...document.querySelectorAll('#sp-cards .sp-card')],i=all.indexOf(card);if(i<0)return;const cols=state.density==='list'?1:Math.max(1,Math.round($('sp-cards').clientWidth/(card.offsetWidth+12)));const j=e.key==='ArrowRight'?i+1:e.key==='ArrowLeft'?i-1:e.key==='ArrowDown'?i+cols:i-cols;const next=all[Math.max(0,Math.min(all.length-1,j))];next.focus();next.scrollIntoView({block:'nearest'})};
var enhancing=false;
function availability(){const ready=shell.dataset.connected==='1'&&!!state.selected;$('sp-generate').disabled=!ready||polling||enhancing||!!pendingGeneration||state.selected?.generatable===false||($('sp-mode').value==='restyle'&&!references.length);$('sp-enhance').disabled=!ready||enhancing||state.selected?.generatable===false;$('sp-estimate').disabled=!ready||enhancing||state.selected?.generatable===false;if(!ready)$('sp-balance').textContent='Generation is not connected yet. Browse styles, save favorites, or copy a prompt.';}
$('sp-mode').onchange=()=>{invalidateEnhancement();availability()};
let references=[],acceptedEnhancement=false,enhanceEpoch=0,reuseAssetId=null;
function invalidateEstimate(){if(!$('sp-result').hidden&&!polling)$('sp-result').textContent='Settings changed. Estimate again before generating.';}
let enhancementStale=false,addedAssets=new Set();
function discardEnhancement(){enhanceEpoch++;acceptedEnhancement=false;enhancementStale=false;$('sp-enhancement').hidden=true;$('sp-enhanced').value='';$('sp-reenhance').hidden=true;invalidateEstimate();}
function invalidateEnhancement(){enhanceEpoch++;acceptedEnhancement=false;invalidateEstimate();if($('sp-enhancement').hidden||!$('sp-enhanced').value.trim()){discardEnhancement();return}enhancementStale=true;$('sp-reenhance').hidden=false;$('sp-enhancement-state').textContent='Your request, style, mode, or references changed after this enhancement. Re-enhance with the current inputs, or accept this text to generate with it as is.'}
function renderReferences(){const box=$('sp-references');box.replaceChildren();references.forEach(ref=>{const card=document.createElement('div'),image=document.createElement('img'),remove=document.createElement('button');image.src=ref.url;image.alt=ref.name;image.style.cssText='width:64px;height:64px;object-fit:cover';remove.textContent='Remove';remove.className='sp-btn secondary';remove.onclick=()=>{references=references.filter(r=>r.id!==ref.id);if(ref.asset_id){addedAssets.delete(ref.asset_id);document.querySelectorAll('.sp-asset.added').forEach(b=>{if(Number(b.dataset.assetId)===ref.asset_id){b.classList.remove('added');b.setAttribute('aria-selected','false')}})}invalidateEnhancement();renderReferences()};card.append(image,remove);box.append(card)});$('sp-ref-count').textContent=`${references.length}/8`;availability();}
// An image picked from the Library fires no input event, so the Home bridge (home-frame.js) cannot see it.
// Home closes a tool without asking while it has heard of no work, so an attached image says so itself.
function reportWork(){if(window.parent!==window)window.parent.postMessage({protocol:'mothership-widget/v1',type:'dirty',payload:{}},location.origin);}
async function addReference(input,assetId=null){if(references.length>=8)throw Error('Use at most eight reference images.');const data=await post('{{ route('admin.home.stylepress.reference') }}',input);if(!data.id)throw Error(data.message||'Image could not be attached.');references.push({...data,asset_id:assetId});reportWork();if(assetId)addedAssets.add(assetId);invalidateEnhancement();renderReferences();}
// The file input is the upload path for references; the library browser below is the other. PR139 dropped this
// binding, so chosen files were never attached and Restyle kept asking for a source image.
$('sp-upload').onchange=async e=>{try{for(const file of e.target.files){const form=new FormData();form.append('image',file);await addReference(form)}}catch(error){showError(error)}finally{e.target.value=''}};
let assetPage=1,assetRequest=0,assetSelection=new Map(),assetScope={kind:'all',directory:null,name:''},assetTreeLoaded=false;
const FOLDERS_URL='{{ route('admin.home.stylepress.folders') }}';
function assetSelectionText(){const n=assetSelection.size,room=8-references.length;$('sp-asset-selection').textContent=n?`${n} selected · ${Math.max(room-n,0)} more can be added`:room>0?`Click images to select them (${room} of 8 reference slots free).`:'All eight reference slots are in use. Remove a reference to add another.';$('sp-asset-add').disabled=!n;$('sp-asset-add').textContent=n?`Add ${n} selected`:'Add selected'}
function toggleAsset(asset,card){if(addedAssets.has(asset.id))return;if(assetSelection.has(asset.id)){assetSelection.delete(asset.id);card.classList.remove('selected');card.setAttribute('aria-selected','false')}else{if(references.length+assetSelection.size>=8){$('sp-asset-status').textContent='Use at most eight reference images. Remove one to add another.';return}assetSelection.set(asset.id,asset);card.classList.add('selected');card.setAttribute('aria-selected','true')}assetSelectionText()}
function assetCard(asset){const card=document.createElement('div');card.setAttribute('role','option');card.tabIndex=0;card.dataset.assetId=asset.id;const added=addedAssets.has(asset.id),selected=assetSelection.has(asset.id);card.className='sp-asset'+(added?' added':selected?' selected':'');card.setAttribute('aria-selected',added||selected?'true':'false');card.title=asset.title||asset.name;const thumb=document.createElement('div');thumb.className='sp-asset-thumb';const image=document.createElement('img');image.src=asset.url;image.alt='';image.loading='lazy';image.decoding='async';image.draggable=false;thumb.append(image);const mark=document.createElement('span');mark.className='sp-asset-mark';mark.textContent='✓';const label=document.createElement('span');label.className='sp-asset-name';label.textContent=asset.title||asset.name;card.append(thumb,mark,label);card.onclick=()=>toggleAsset(asset,card);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleAsset(asset,card)}};return card}
function scopeLabel(){return assetScope.kind==='folder'?assetScope.name:assetScope.kind==='recent'?'Added in the last 30 days':assetScope.kind==='favorites'?'Favorites':'All images'}
function paintCrumbs(q){const box=$('sp-asset-crumbs');box.replaceChildren();if(q){box.append('Search results for ');const b=document.createElement('b');b.textContent=`“${q}”`;box.append(b);box.append(assetScope.kind==='favorites'?' in your favorites':' across all permitted images');return}if(assetScope.kind==='folder'&&assetScope.path){assetScope.path.forEach((name,i)=>{if(i){box.append(' › ')}const el=document.createElement(i===assetScope.path.length-1?'b':'span');el.textContent=name;box.append(el)});return}const b=document.createElement('b');b.textContent=scopeLabel();box.append(b)}
async function findAssets(append=false){const box=$('sp-asset-results'),status=$('sp-asset-status'),q=$('sp-asset-search').value.trim();const scope=q?(assetScope.kind==='favorites'?'favorites':'all'):assetScope.kind;if(!append){assetPage=1;box.replaceChildren();status.textContent='Loading…';paintCrumbs(q)}const request=++assetRequest;try{const params=new URLSearchParams({scope,page:String(assetPage),q,sort:$('sp-asset-sort').value});if(scope==='folder')params.set('directory',String(assetScope.directory));const response=await fetch('{{ route('admin.home.stylepress.assets') }}?'+params.toString(),{headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.message||'Image search is unavailable right now ('+response.status+').');if(request!==assetRequest)return;if(!append)box.replaceChildren();box.querySelector('.sp-asset-more')?.remove();const shown=box.querySelectorAll('.sp-asset').length+(data.assets||[]).length;const more=data.has_more?'+':'';status.textContent=q?`${shown}${more} image${shown===1?'':'s'} matching “${q}”`:scope==='folder'?`${shown}${more} image${shown===1?'':'s'} in this folder`:scope==='recent'?`${shown} image${shown===1?'':'s'} added in the last 30 days`:scope==='favorites'?`${shown} favorite image${shown===1?'':'s'}`:`${shown}${more} permitted image${shown===1?'':'s'}`;(data.assets||[]).forEach(asset=>box.append(assetCard(asset)));if(data.has_more){const btn=document.createElement('button');btn.type='button';btn.className='sp-btn secondary sp-asset-more';btn.textContent='Show more';btn.onclick=()=>{btn.disabled=true;btn.textContent='Loading…';assetPage++;findAssets(true)};box.append(btn)}if(!box.childElementCount)status.textContent=q?`No permitted images match “${q}”. Try another word from the file name, title, or a tag.`:scope==='favorites'?'No favorite images yet. Star images in the library to see them here.':scope==='recent'?'No permitted images from the last 30 days.':scope==='folder'?'No images in this folder. Subfolders are listed on the left.':'No permitted images yet.'}catch(error){if(request===assetRequest)status.textContent=error.message||String(error)}}
function folderEntry(dir,depth,pathNames){const wrap=document.createElement('div');const entry=document.createElement('button');entry.type='button';entry.className='sp-lib-entry';entry.dataset.kind='folder';entry.dataset.directory=dir.id;entry.style.paddingLeft=(8+depth*4)+'px';const toggle=document.createElement('span');toggle.className='sp-lib-toggle'+(dir.has_children?'':' leaf');toggle.textContent='▸';const name=document.createElement('span');name.className='sp-lib-name';name.textContent=dir.name;entry.append(toggle,name);const children=document.createElement('div');children.className='sp-lib-children';children.hidden=true;let loaded=false,offset=0;const path=[...pathNames,dir.name];async function loadChildren(){const response=await fetch(FOLDERS_URL+'?parent='+encodeURIComponent(dir.id)+'&offset='+offset+'&limit=100',{headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.message||'Folders are unavailable.');children.querySelector('.sp-lib-more')?.remove();(data.data||[]).forEach(child=>children.append(folderEntry(child,depth+1,path)));offset+=(data.data||[]).length;if(data.has_more){const more=document.createElement('button');more.type='button';more.className='sp-lib-more';more.textContent='More folders…';more.onclick=()=>loadChildren().catch(e=>{$('sp-asset-status').textContent=e.message});children.append(more)}loaded=true}
toggle.onclick=async e=>{e.stopPropagation();if(!dir.has_children)return;children.hidden=!children.hidden;toggle.textContent=children.hidden?'▸':'▾';if(!children.hidden&&!loaded){toggle.textContent='…';try{await loadChildren()}catch(err){$('sp-asset-status').textContent=err.message}toggle.textContent='▾'}};
entry.onclick=()=>{assetScope={kind:'folder',directory:dir.id,name:dir.name,path};document.querySelectorAll('#sp-lib-tree .sp-lib-entry').forEach(b=>b.classList.toggle('active',b===entry));$('sp-asset-search').value='';findAssets();if(dir.has_children&&children.hidden)toggle.onclick(new Event('click'))};
if(Array.isArray(dir.children)&&dir.children.length){dir.children.forEach(child=>children.append(folderEntry(child,depth+1,path)));loaded=!dir.children_has_more;offset=dir.children.length;if(dir.children_has_more){const more=document.createElement('button');more.type='button';more.className='sp-lib-more';more.textContent='More folders…';more.onclick=()=>loadChildren().catch(e=>{$('sp-asset-status').textContent=e.message});children.append(more)}}
wrap.append(entry,children);return wrap}
async function loadFolderTree(){if(assetTreeLoaded)return;const host=$('sp-lib-folders');try{const response=await fetch(FOLDERS_URL,{headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.message||'Folders are unavailable.');host.replaceChildren();(data.data||[]).forEach(dir=>host.append(folderEntry(dir,0,[])));if(!host.childElementCount)host.innerHTML='<p class="sp-asset-status" style="padding:4px 8px">No folders are shared with you.</p>';assetTreeLoaded=true}catch(error){host.innerHTML='';const p=document.createElement('p');p.className='sp-asset-status';p.style.padding='4px 8px';p.textContent=error.message||'Folders are unavailable.';host.append(p)}}
$('sp-lib-tree').addEventListener('click',e=>{const b=e.target.closest('.sp-lib-entry[data-kind]');if(!b||b.dataset.kind==='folder')return;assetScope={kind:b.dataset.kind,directory:null,name:''};document.querySelectorAll('#sp-lib-tree .sp-lib-entry').forEach(x=>x.classList.toggle('active',x===b));$('sp-asset-search').value='';findAssets()});
$('sp-asset-sort').onchange=()=>findAssets();
let assetSearchTimer=null;const assetDialog=$('sp-asset-dialog');
function openAssetBrowser(){assetSelection.clear();assetSelectionText();if(typeof assetDialog.showModal==='function'){if(!assetDialog.open)assetDialog.showModal()}else{assetDialog.setAttribute('open','')}loadFolderTree();findAssets();setTimeout(()=>$('sp-asset-search').focus(),50)}
let assetAdding=false;function closeAssetBrowser(){if(assetAdding)return;assetSelection.clear();assetRequest++;if(assetDialog.open&&typeof assetDialog.close==='function')assetDialog.close();else assetDialog.removeAttribute('open')}
$('sp-browse-assets').onclick=openAssetBrowser;$('sp-asset-close').onclick=closeAssetBrowser;$('sp-asset-cancel').onclick=closeAssetBrowser;assetDialog.addEventListener('cancel',e=>{e.preventDefault();closeAssetBrowser()});assetDialog.onclick=e=>{if(e.target===assetDialog)closeAssetBrowser()};
$('sp-asset-add').onclick=async()=>{const chosen=[...assetSelection.values()];if(!chosen.length||assetAdding)return;assetAdding=true;['sp-asset-add','sp-asset-cancel','sp-asset-close'].forEach(id=>$(id).disabled=true);$('sp-asset-add').textContent='Adding…';let failed=null;try{for(const asset of chosen){try{await addReference({asset_id:asset.id},asset.id)}catch(error){failed=error;break}}}finally{assetAdding=false;['sp-asset-cancel','sp-asset-close'].forEach(id=>$(id).disabled=false)}if(failed){$('sp-asset-status').textContent=failed.message||String(failed);assetSelection.clear();document.querySelectorAll('.sp-asset').forEach(b=>{const id=Number(b.dataset.assetId);b.classList.toggle('added',addedAssets.has(id));b.classList.remove('selected');b.setAttribute('aria-selected',addedAssets.has(id)?'true':'false')});assetSelectionText();return}closeAssetBrowser()};
$('sp-asset-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(assetSearchTimer);findAssets()}};$('sp-asset-search').oninput=()=>{clearTimeout(assetSearchTimer);assetSearchTimer=setTimeout(()=>findAssets(),350)};
function showError(error){$('sp-result').hidden=false;$('sp-result').textContent=error.message||String(error);}
async function enhance(){if(!$('sp-prompt').value.trim()){showError(Error('Describe what you want to create first, then enhance that request.'));$('sp-prompt').focus();return}if(charCount($('sp-prompt').value)>4000){showError(Error('Enhance accepts requests up to 4000 characters. Shorten the request, or generate without enhancement (up to 5000).'));$('sp-prompt').focus();return}if($('sp-mode').value==='restyle'&&!references.length){showError(Error('Restyle needs a source image. Add a reference image, then enhance.'));return}const epoch=++enhanceEpoch;enhancing=true;['sp-reenhance','sp-enhanced','sp-accept-enhanced','sp-discard-enhanced'].forEach(id=>$(id).disabled=true);availability();$('sp-result').hidden=false;$('sp-result').textContent='Enhancing your request… Generate unlocks when it finishes.';try{const data=await post('{{ route('admin.home.stylepress.enhance') }}',payload());if(!data.ok)throw Error(data.message||'Enhancement unavailable.');if(epoch!==enhanceEpoch)return;acceptedEnhancement=true;enhancementStale=false;$('sp-reenhance').hidden=true;$('sp-enhanced').value=data.enhanced_prompt;$('sp-enhancement').hidden=false;$('sp-enhancement-state').textContent='Enhanced request accepted. Generate uses this text; edit it here if you want changes, or discard it to use your original request.';invalidateEstimate();$('sp-result').textContent='Enhancement ready. Estimate or generate with the enhanced request.'}catch(error){showError(error)}finally{enhancing=false;['sp-reenhance','sp-enhanced','sp-accept-enhanced','sp-discard-enhanced'].forEach(id=>$(id).disabled=false);availability()}}
$('sp-enhance').onclick=enhance;$('sp-reenhance').onclick=enhance;
$('sp-accept-enhanced').onclick=()=>{acceptedEnhancement=true;enhancementStale=false;$('sp-reenhance').hidden=true;$('sp-enhancement-state').textContent='Accepted. Generate will apply the complete style template to this edited request.';invalidateEstimate()};
$('sp-enhanced').oninput=()=>{enhanceEpoch++;acceptedEnhancement=false;$('sp-enhancement-state').textContent='Edited. Accept this version to use it, or Generate will ask which request to use.';invalidateEstimate()};
$('sp-discard-enhanced').onclick=discardEnhancement;
// Count and trim in Unicode code points to match the server's mb_strlen limits (5000 request, 4000 enhance); never split a surrogate pair.
const chars=v=>Array.from(String(v??''));const charCount=v=>chars(v).length;const trimChars=(v,n)=>chars(v).slice(0,n).join('');
function promptCount(){const box=$('sp-prompt');if(charCount(box.value)>5000){const at=box.selectionStart;box.value=trimChars(box.value,5000);box.setSelectionRange(Math.min(at,box.value.length),Math.min(at,box.value.length))}const n=charCount(box.value);$('sp-prompt-count').textContent=`${n} / 5000 characters · Enhance accepts up to 4000`;$('sp-prompt-count').style.color=n>4000?'#ffd166':''}
$('sp-prompt').oninput=()=>{promptCount();invalidateEnhancement()};promptCount();
['sp-output-aspect','sp-quality','sp-resolution','sp-model'].forEach(id=>$(id).onchange=invalidateEstimate);
async function reuse(){const id=new URL(location.href).searchParams.get('reuse_asset');if(!id||!/^\d+$/.test(id))return;try{const response=await fetch('{{ url('admin/dam/assets') }}/'+id+'/generation',{headers:{Accept:'application/json'}});if(!response.ok)throw Error('This generation is unavailable.');const data=await response.json(),manifest=data.manifest||data.generation?.manifest||data.generation||data;if(!manifest.style?.slug||!manifest.style?.template)throw Error('No reusable style snapshot was recorded. Copy the saved prompt or choose this image as a reference.');const style=styles.find(s=>s.slug===manifest.style?.slug);if(style)select(style.slug);else if(manifest.style?.slug){styles.push({...manifest.style,categoryLabel:manifest.style.categoryLabel||manifest.style.category||'Historical style'});select(manifest.style.slug)}reuseAssetId=Number(id);if(manifest.style){state.selected={...state.selected,...manifest.style,categoryLabel:manifest.style.categoryLabel||manifest.style.category||'Historical style'};detail()}if(manifest.style?.version!==catalog.version)showError(Error('Restored the original style snapshot. Selecting another style uses the current catalog.'));const restoredRequest=String(manifest.original_prompt||manifest.prompt||'');$('sp-prompt').value=trimChars(restoredRequest,5000);promptCount();if(charCount(restoredRequest)>5000)showError(Error('The saved request was longer than 5000 characters and was trimmed to fit.'));const settings=manifest.settings||{};['aspect_ratio','quality','resolution'].forEach((key,i)=>{const control=$(['sp-output-aspect','sp-quality','sp-resolution'][i]);if([...control.options].some(o=>o.value===settings[key]))control.value=settings[key]});if(settings.model){const choice=settings.model+(settings.variant?':'+settings.variant:'');if([...$('sp-model').options].some(o=>o.value===choice))$('sp-model').value=choice}$('sp-mode').value=settings.mode||'create';for(const ref of (data.reference_urls||[]).filter(r=>typeof r==='string'||r.mime?.startsWith('image/'))){const address=typeof ref==='string'?ref:ref.url;const url=new URL(address,location.href);if(url.origin!==location.origin)throw Error('Reference address is unavailable.');const result=await fetch(url);if(!result.ok)throw Error('A saved reference is unavailable.');const form=new FormData();form.append('image',await result.blob(),ref.name||'reference.png');await addReference(form)}if(manifest.enhanced_prompt){$('sp-enhanced').value=manifest.enhanced_prompt;$('sp-enhancement').hidden=false;acceptedEnhancement=true;$('sp-enhancement-state').textContent='Restored enhanced request. Review before generating.'}availability()}catch(error){showError(error)}}
reuse();
rerender();availability();if(shell.dataset.connected==='1')balance();if(pendingGeneration)pollGeneration(pendingGeneration)})();
</script>

</body></html>
